config.script:
if event.key == "Enter":
    try:
        val = self.props.text.strip()  # Get scanned value

        if val:
            # Define tag paths
            slotTags = [
                "[default]sander_falldown/falldown/barcode/scanQueue/slot1",
                "[default]sander_falldown/falldown/barcode/scanQueue/slot2",
                "[default]sander_falldown/falldown/barcode/scanQueue/slot3",
                "[default]sander_falldown/falldown/barcode/scanQueue/slot4"
            ]

            # Read current slot values
            slots = [q.value for q in system.tag.readBlocking(slotTags)]

            # Find first empty slot
            if not slots[0]:
                system.tag.writeBlocking([slotTags[0]], [val])
            elif not slots[1]:
                system.tag.writeBlocking([slotTags[1]], [val])
            elif not slots[2]:
                system.tag.writeBlocking([slotTags[2]], [val])
            elif not slots[3]:
                system.tag.writeBlocking([slotTags[3]], [val])
            else:
                # All slots full → log
                system.util.getLogger("BarcodeQueue").info(
                    "All slots full, scan ignored: {}".format(val)
                )

            # --- Reset field + refocus ---
            system.util.getLogger("BarcodeQueue").info("Resetting ScanInput now...")
            self.props.text = ""

            # Delay clear in case of browser redraw
            def clearAgain():
                self.props.text = ""
                self.focus()

            system.util.invokeLater(clearAgain, 200)

        else:
            system.util.getLogger("BarcodeQueue").info("Ignored empty scan input")

    except Exception as e:
        system.util.getLogger("BarcodeQueue").error(
            "Scan handler failed: {}".format(e)
        )

if not self.view.custom.allowBarcodeFocus:
    return

try:
    comp = self.getChild("FlexContainer_1/FlexContainer_0/FlexContainer_9/ScanInput")
    if comp:
        comp.focus()
    else:
        system.util.getLogger("BarcodeFocus").warn("ScanInput not found at expected path")
except Exception as e:
    system.util.getLogger("BarcodeFocus").warn("Focus script failed: {}".format(e))

